import { Meta, StoryObj } from "@storybook/react";
import { expect, fn, userEvent, within } from "storybook/test";
import { ComponentProps, useState } from "react";
import { RadioButtons, RadioOption } from "./radio-buttons";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";
import styles from "./radio-buttons.stories.module.less";

// The selected value is controlled by the parent, so the stories keep it in local state and forward
// every change to the onChange arg so it still shows up in the Actions panel.
const InteractiveRadioButtons = (props: ComponentProps<typeof RadioButtons>) => {
  const [value, setValue] = useState(props.value);
  return (
    <RadioButtons
      {...props}
      value={value}
      onChange={(name, newValue) => {
        setValue(newValue);
        props.onChange(name, newValue);
      }}
    />
  );
};

const ticketTypes: Array<RadioOption> = [
  { value: "adult", label: "Vuxen" },
  { value: "child", label: "Barn" },
  { value: "senior", label: "Senior" },
];

// Gives every option an id unique to one variant, so several groups can share the same option values on one page
// without duplicate input ids or labels resolving to another group's inputs.
const withIdPrefix = (prefix: string, options: Array<RadioOption>): Array<RadioOption> =>
  options.map((option) => ({ ...option, id: `${prefix}-${option.value}` }));

const ticketTypesWithDisabledOption: Array<RadioOption> = [
  { value: "adult", label: "Vuxen" },
  { value: "child", label: "Barn", disabled: true },
  { value: "senior", label: "Senior" },
];

// Declared at module level on purpose: an element created inside the render function carries React's
// internal owner reference, and Storybook's source-snippet generator then tries to stringify the whole
// fiber tree (RangeError: Invalid string length).
const ticketTypesWithReactNodeLabel: Array<RadioOption> = [
  {
    value: "adult",
    label: (
      <span>
        Vuxen <i>(18+)</i>
      </span>
    ),
  },
  { value: "child", label: "Barn" },
  { value: "senior", label: "Senior" },
];

const meta = {
  title: "Primitives/Form Fields/Radio Buttons",
  component: RadioButtons,
  parameters: {
    docs: {
      description: {
        component:
          "A group of radio inputs rendered from `options`, where the option whose `value` matches the `value` " +
          "prop is checked. Selecting an option calls `onChange(name, value)`; the parent owns the selected " +
          "value. Each option's label can be any ReactNode and its input id falls back to the option value. An " +
          "optional group `label` is rendered with `InputLabel` without an `htmlFor`, so it is not associated " +
          "with any input or with the `radiogroup`.\n\n" +
          "This is the unstyled base behind `StyledRadioButtons`, so it renders no look of its own and the " +
          "consumer supplies the whole appearance through a styling contract: the native input is visually " +
          "hidden and carries the global class `input`, the label carries `labelClassName` plus the global " +
          "classes `selected` and `disabled`, and `wrapperClassName`, `radioItemsWrapperClassName` and " +
          "`radioItemClassName` target the wrapper, the `radiogroup` and each option. Consumers either style " +
          "those classes or replace the label entirely with a ReactNode, which is what the gift card theme " +
          "picker and the price variation selector do. Because a bare group shows no selection at all, the " +
          "stories below add story-local demo styling through `labelClassName`; `Variant styling` shows the " +
          "component both with and without it.",
      },
    },
  },
  argTypes: {
    name: { table: { disable: true } },
    onChange: { table: { disable: true } },
    wrapperClassName: { table: { disable: true } },
    radioItemsWrapperClassName: { table: { disable: true } },
    radioItemClassName: { table: { disable: true } },
    labelClassName: { table: { disable: true } },
  },
  args: {
    name: "ticketType",
    label: "Biljettyp",
    options: ticketTypes,
    value: "adult",
    onChange: fn(),
    // Demo styling from the story's own stylesheet, so the stories show a readable radio group. The
    // component itself draws nothing; see the description for the classes a consumer styles.
    labelClassName: styles.demoLabel,
    radioItemsWrapperClassName: styles.demoOptions,
  },
  render: (args) => <InteractiveRadioButtons {...args} />,
} satisfies Meta<typeof RadioButtons>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {};

export const VariantStyling: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="Consumer styling (what the component draws on its own)" variantType="other">
      <Variant label="no consumer styling: hidden inputs and unstyled labels, no visible selection">
        <RadioButtons
          {...args}
          name="unstyled"
          options={withIdPrefix("unstyled", ticketTypes)}
          labelClassName={undefined}
          radioItemsWrapperClassName={undefined}
        />
      </Variant>
      <Variant label="story-local demo styling through labelClassName (selected and disabled classes)">
        <RadioButtons {...args} name="demoStyled" options={withIdPrefix("demoStyled", ticketTypesWithDisabledOption)} />
      </Variant>
    </ShowcaseLayout>
  ),
};

export const VariantStates: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout
      title="Label and option states (no group label, disabled option, ReactNode label, nothing selected)"
      variantType="other"
    >
      <Variant label="no group label">
        <RadioButtons {...args} name="noLabel" options={withIdPrefix("noLabel", ticketTypes)} label={undefined} />
      </Variant>
      <Variant label="disabled option">
        <RadioButtons
          {...args}
          name="disabledOption"
          options={withIdPrefix("disabledOption", ticketTypesWithDisabledOption)}
        />
      </Variant>
      <Variant label="ReactNode label">
        <RadioButtons
          {...args}
          name="reactNodeLabel"
          options={withIdPrefix("reactNodeLabel", ticketTypesWithReactNodeLabel)}
        />
      </Variant>
      <Variant label="nothing selected">
        <RadioButtons
          {...args}
          name="nothingSelected"
          options={withIdPrefix("nothingSelected", ticketTypes)}
          value={undefined}
        />
      </Variant>
    </ShowcaseLayout>
  ),
};

const onChangeSpy = fn();

export const TestSelectOption: Story = {
  args: {
    onChange: onChangeSpy,
  },
  play: async ({ canvasElement }) => {
    onChangeSpy.mockClear();
    const canvas = within(canvasElement);
    const childRadio = canvas.getByRole("radio", { name: "Barn" });
    await userEvent.click(childRadio);
    await expect(onChangeSpy).toHaveBeenCalledTimes(1);
    await expect(onChangeSpy).toHaveBeenCalledWith("ticketType", "child");
    await expect(childRadio).toBeChecked();
  },
};
