import styles from "./input-label.module.less";
import { multipleClassNames } from "@/core/helpers/string-helper";
import { useTranslation } from "react-i18next";

type InputLabelProps = {
  label: string;
  contentfulLabelId?: string;
  /** Name (id) of the input the label belongs to, rendered as the `htmlFor` attribute. */
  inputName?: string;
  /** Extra text shown in parentheses right after the label, e.g. an age range. */
  additionalText?: string;
  /** Appends the translated "mandatory" label in parentheses ("Obligatoriskt" in Swedish); the stylesheet renders
   * the marker lowercase, so it displays as "(obligatoriskt)". */
  isRequired?: boolean;
  /** Uses the smaller `p_small` text style instead of `body-m`, for labels inside a grouped input. */
  isGroupedInput?: boolean;
} & Omit<React.HTMLProps<HTMLLabelElement>, "htmlFor" | "className">;

export const InputLabel = ({
  label,
  contentfulLabelId,
  inputName,
  additionalText,
  isRequired,
  isGroupedInput,
  ...rest
}: InputLabelProps) => {
  const { t } = useTranslation();
  return (
    <label
      data-contentful-label-id={contentfulLabelId}
      htmlFor={inputName}
      className={multipleClassNames(styles.label, isGroupedInput ? "p_small" : "body-m", "bold")}
      {...rest}
    >
      {label}
      {additionalText && <span className={styles.additionalText}>{` (${additionalText})`}</span>}
      {isRequired && (
        <span data-contentful-label-id="mandatory" className={`${styles.required} body-s bold`}>
          {` (${t("mandatory")})`}
        </span>
      )}
    </label>
  );
};
