import { ReactNode } from "react";
import styles from "./radio-buttons.module.less";
import { isNonEmptyArray } from "@/core/helpers";
import { multipleClassNames } from "@/core/helpers/string-helper";
import { InputLabel } from "@/core/components/primitives/input-label/input-label";

export type RadioOption = {
  /** Visible content of the option's label. Accepts any ReactNode, not just a string. */
  label: string | ReactNode;
  /** Value reported through `onChange` when the option is selected. */
  value: string;
  /** Id of the underlying radio input (also used as `data-testid`). Falls back to `value`. */
  id?: string;
  /** Disables the radio input and adds the global `disabled` class to its label. */
  disabled?: boolean;
};

type RadioButtonsProps = {
  name: string;
  /** The options to render, one radio input plus label per entry. An empty array still renders the wrapper,
   * fieldset, group label and the empty `radiogroup`; only the option items are skipped. */
  options: Array<RadioOption>;
  onChange: (name: string, value: string) => void;
  /** Value of the currently selected option. Leave undefined to render the group with nothing selected. */
  value?: string;
  /** Group label rendered above the options with `InputLabel`. Omitted when not set. */
  label?: string;
  /** Class name for the outermost wrapping div. */
  wrapperClassName?: string;
  /** Class name for the div wrapping each radio input and its label. */
  radioItemClassName?: string;
  /** Class name for the `radiogroup` element that wraps all options. */
  radioItemsWrapperClassName?: string;
  /** Class name for each option's `<label>` element. */
  labelClassName?: string;
};

export const RadioButtons = ({
  name,
  options,
  onChange,
  value,
  label,
  wrapperClassName = "",
  radioItemClassName = "",
  radioItemsWrapperClassName = "",
  labelClassName = "",
}: RadioButtonsProps) => {
  return (
    <div key={name} className={wrapperClassName}>
      <fieldset className={styles.fieldset}>
        {label && <InputLabel label={label} />}
        <div role="radiogroup" className={multipleClassNames(styles.radioItemsWrapper, radioItemsWrapperClassName)}>
          {isNonEmptyArray(options) &&
            options.map((item, index) => {
              const selected = item.value === value;

              return (
                <div className={radioItemClassName} key={item.value + index}>
                  <input
                    className={multipleClassNames(styles.input, "input")}
                    type="radio"
                    id={item.id ?? item.value}
                    data-testid={item.id ?? item.value}
                    name={name}
                    value={item.value}
                    checked={selected}
                    onChange={(event) => onChange(name, event.target.value)}
                    disabled={item.disabled}
                    aria-disabled={item.disabled}
                  />
                  <label
                    className={multipleClassNames(
                      styles.itemWrapper,
                      labelClassName,
                      selected && "selected",
                      item.disabled && "disabled",
                    )}
                    htmlFor={item.id ?? item.value}
                  >
                    {item.label}
                  </label>
                </div>
              );
            })}
        </div>
      </fieldset>
    </div>
  );
};
